use vstd::prelude::*;

verus! {

fn reverse(a: &mut Vec<i32>)
    ensures
        a@.len() == old(a)@.len(),
        forall |i: int|
            0 <= i < old(a)@.len()
            ==> a@[i] == old(a)@[old(a)@.len() - 1 - i],
{
    let n: usize = a.len();
    let mut i: usize = 0;

    while i < n / 2
        invariant
            n == a.len(),
            a@.len() == old(a)@.len(),
            i <= n / 2,

            // Everything strictly before i has already been swapped into its final place:
            forall |k: int|
                0 <= k < i as int
                ==> a@[k] == old(a)@[n as int - 1 - k],

            // Everything strictly after (n-1-i) has already been swapped into its final place:
            forall |k: int|
                (n as int - i as int) <= k < n as int
                ==> a@[k] == old(a)@[n as int - 1 - k],

            // The middle (unswapped) region still equals the old vector:
            forall |k: int|
                i as int <= k < (n as int - i as int)
                ==> a@[k] == old(a)@[k],
        decreases (n / 2) - i,
    {
        let j: usize = n - 1 - i;

        // Swap a[i] and a[j]
        let tmp = a[i];
        a.set(i, a[j]);
        a.set(j, tmp);

        i = i + 1;
    }
}

} // verus!

